// "Find a measure" on the All measures screen. A row is found by the name it shows, by its measure's full name
// and by everyday words a person may type (WORDS). Pure functions, so the automatic checks can run them in Node.
// The short names of the lists live here too, because the search must know every name a row can show.
// Code generated by Claude (Anthropic), an AI system.

// Short names for the lists; the full name stays on the measure's own page.
export const SHORT = { vo2max: 'Aerobic capacity', cabinO2: 'Cabin oxygen', noise: 'Cabin noise', spo2: 'Blood oxygen', sleepQuality: 'Sleep quality', bodyMass: 'Body mass', radiation: 'Radiation dose', mood: 'Mood', attitude: 'Energy' };
export const shortLabel = (cell) => SHORT[cell.indicator] || cell.label;

// Everyday words a person may type in "Find a measure".
export const WORDS = {
  pulse: 'pulse heart rate hr bpm heartbeat', bp: 'bp blood pressure systolic diastolic hypertension', spo2: 'oxygen o2 sats saturation spo2 pulse ox',
  temp: 'temperature fever temp', resp: 'breathing respiration breaths', sleep: 'sleep hours rest', fluid: 'water drink fluid hydration',
  glucose: 'sugar glucose blood sugar', bodyMass: 'weight mass body', vo2max: 'fitness aerobic vo2 cardio exercise', strength: 'muscle strength',
  bone: 'bone density dexa', eyePressure: 'eye vision iop', hearing: 'ear hearing audiogram', radiation: 'radiation dose msv dosimeter',
  mood: 'mood feeling', attitude: 'energy tired fatigue sleepy exhausted samn perelli', sleepQuality: 'sleep quality rest', cognition: 'thinking cognition memory test winscat monthly', reaction: 'reaction reflex speed alert alertness fatigue pvt rst test',
  xray: 'x-ray xray image', exercise: 'exercise workout training treadmill bike ared cevis', visionCheck: 'vision eye eyes amsler sans sight', octChange: 'oct retina eye eyes sans', octScan: 'oct scan eye image retina', ecg: 'ecg ekg heart tracing', ultrasound: 'ultrasound echo scan image', camera: 'camera video chest sleep',
  co2: 'co2 carbon dioxide air', cabinO2: 'oxygen o2 air', cabinPressure: 'pressure cabin air', noise: 'noise sound loud db', cabinTemp: 'temperature cabin air',
};

// Lower case, one space between words, the same apostrophe however it was typed.
export const normalFind = (s) => String(s ?? '').toLowerCase().replace(/[‘’ʼ`´]/g, "'").replace(/\s+/g, ' ').trim();

// The text a row is searched in: the name on the row, the measure's full name and the everyday words.
export function findText({ name = '', label = '', words = '' } = {}) {
  return normalFind([name, label, words].filter(Boolean).join(' | '));
}

// Does a query find this text? An empty query finds everything.
export function findHit(query, text) {
  const q = normalFind(query);
  return !q || normalFind(text).includes(q);
}
